#!/usr/bin/env python3
"""Read-only helpers for obtaining BL3 values from local save files.

The bundled bl3-cli-saveedit parser is used only to decrypt and parse saves.
This module never writes a save file.
"""

from __future__ import annotations

import os
from pathlib import Path
import sys
from typing import Any


# bl3-cli-saveedit 1.18.0 ships protobuf sources generated by an older protoc.
# The pure-Python protobuf implementation keeps those sources compatible with
# current protobuf releases bundled by the build environment.
os.environ.setdefault("PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION", "python")

VENDOR_DIR = Path(__file__).resolve().parent / "vendor"
if VENDOR_DIR.is_dir() and str(VENDOR_DIR) not in sys.path:
    sys.path.insert(0, str(VENDOR_DIR))

from bl3save.bl3profile import BL3Profile  # noqa: E402
from bl3save.bl3save import BL3Save  # noqa: E402


def default_save_root() -> Path:
    documents = Path(os.environ.get("USERPROFILE", str(Path.home()))) / "Documents"
    return documents / "My Games" / "Borderlands 3" / "Saved" / "SaveGames"


def character_snapshots(root: str | Path | None = None) -> list[dict[str, Any]]:
    """Return parseable character saves, newest first, without modifying them."""
    save_root = Path(root) if root else default_save_root()
    snapshots: list[dict[str, Any]] = []
    if not save_root.is_dir():
        return snapshots

    for path in save_root.glob("*/*.sav"):
        if path.name.casefold() == "profile.sav":
            continue
        try:
            save = BL3Save(str(path))
            snapshots.append(
                {
                    "path": str(path),
                    "modified": path.stat().st_mtime,
                    "name": save.get_char_name(),
                    "level": int(save.get_level()),
                    "xp": int(save.get_xp()),
                    "money": int(save.get_money()),
                    "eridium": int(save.get_eridium()),
                    "skill_points": int(save.save.ability_data.ability_points),
                }
            )
        except Exception:
            # A cloud conflict, backup, or save from another game should not
            # prevent the trainer from using the remaining valid saves.
            continue
    snapshots.sort(key=lambda item: float(item["modified"]), reverse=True)
    return snapshots


def profile_snapshots(root: str | Path | None = None) -> list[dict[str, Any]]:
    """Return parseable BL3 profiles and shared golden-key counts."""
    save_root = Path(root) if root else default_save_root()
    snapshots: list[dict[str, Any]] = []
    if not save_root.is_dir():
        return snapshots

    for path in save_root.glob("*/profile.sav"):
        try:
            profile = BL3Profile(str(path))
            snapshots.append(
                {
                    "path": str(path),
                    "modified": path.stat().st_mtime,
                    "golden_keys": int(profile.get_golden_keys()),
                }
            )
        except Exception:
            continue
    snapshots.sort(key=lambda item: float(item["modified"]), reverse=True)
    return snapshots

